ext('c10_eng_ch9',[
C("🌾","गाँव और शहर की तुलना",["गाँव: शांति, खुली हवा, हरियाली","शहर: भीड़, शोर, धुआँ","गाँव में प्रकृति का साथ","शहर में सुविधा, पर तनाव"],"कविता की शुरुआत एक बड़ी तुलना से होती है, गाँव और शहर की। गाँव में खुली हवा है, हरे खेत हैं, पक्षियों की आवाज़ें हैं और जीवन शांत है। शहर में ऊँची इमारतें, भीड़, शोर और धुआँ है। कवि का मानना है कि गाँव प्रकृति का बनाया हुआ है और शहर इंसान का। प्रकृति की रचना में जो शुद्धता और सुकून है, वह इंसान की रचना में हमेशा नहीं मिलता। पर यह भी सच है कि शहर में सुविधाएँ ज़्यादा हैं। इसलिए कविता पढ़ते समय कवि की दृष्टि और आज की हक़ीक़त, दोनों को याद रखिए।"),
C("✍️","विलियम काउपर",["इंग्लैंड के कवि, 18वीं सदी","प्रकृति और गाँव के प्रेमी","लंबी कविता द टास्क का अंश","सरल भाषा, शांत भाव"],"कवि विलियम काउपर अठारहवीं सदी के इंग्लैंड के कवि थे। वे शहर की भागदौड़ से दूर गाँव के शांत वातावरण में रहना पसंद करते थे और प्रकृति पर लिखते थे। उनका नाम कभी कूपर भी उच्चारित किया जाता है। यह पाठ उनकी लंबी कविता द टास्क का एक अंश है, जो उनकी सबसे प्रसिद्ध रचना मानी जाती है। उनकी भाषा सरल है और भाव शांत। परीक्षा में कवि का नाम, देश और कविता की मूल पंक्ति का भाव अक्सर पूछा जाता है, इसलिए पहली पंक्ति का अर्थ अच्छे से याद रखिए।"),
C("🏡","कंट्री का असली अर्थ",["यहाँ कंट्री यानी देहात","देश नहीं, गाँव का क्षेत्र","टाउन यानी शहर","शब्द के संदर्भ से अर्थ समझिए"],"कविता की पहली पंक्ति में कंट्री शब्द आता है। यहाँ इसका मतलब देश नहीं, बल्कि देहात या ग्रामीण क्षेत्र है। यह अंग्रेज़ी का एक रोचक पहलू है कि एक ही शब्द के अलग-अलग संदर्भ में अलग अर्थ होते हैं। कंट्रीसाइड यानी ग्रामीण इलाक़ा, और टाउन यानी शहर। इसलिए पहली पंक्ति का अर्थ है कि ईश्वर ने गाँव बनाया और मनुष्य ने शहर। जब भी किसी शब्द का अर्थ अटपटा लगे, तो वाक्य और संदर्भ देखिए, तभी सही अर्थ समझ आता है।"),
C("💚","स्वास्थ्य और सद्गुण",["खेत और बाग़ में स्वास्थ्य","सद्गुण का विकास","जीवन के कड़वे घूँट मीठे","काम करने वाले का सुख"],"कवि कहते हैं कि स्वास्थ्य और अच्छे गुण जैसे उपहार जो जीवन की कड़वाहट को मीठा कर सकते हैं, सबसे ज़्यादा खेतों और बाग़ों में ही मिलते हैं। जब आदमी सुबह उठकर खेत में काम करता है, ताज़ी हवा लेता है और शारीरिक मेहनत करता है, तो उसका शरीर भी स्वस्थ रहता है और मन भी शांत। सादा जीवन अपने आप में सद्गुण सिखाता है, जैसे मेहनत, संतोष और दया। इसीलिए हमारे किसान भाई भले साधन में कम हों, पर कई बार उनका मन अमीर शहरी से ज़्यादा सुखी होता है।"),
C("😏","शहर के अमीरों पर व्यंग्य",["रथ और पालकी में घूमने वाले","आलस की थकान","वास्तविक आनंद से दूर","कवि का हल्का व्यंग्य"],"कविता में कवि शहर के अमीरों पर हल्का व्यंग्य करते हैं। वे उन लोगों की बात करते हैं जो रथ या पालकी में घूमते हैं, यानी ख़ुद मेहनत नहीं करते। उन्हें कोई थकान नहीं होती, सिवाय आलस की थकान के। मतलब, वे आराम में रहते हैं पर जीवन का असली आनंद नहीं ले पाते। व्यंग्य का अर्थ है हँसी-हँसी में किसी कमी की ओर इशारा करना। कवि सीधे डाँट नहीं रहे, बल्कि मुस्कुराकर समझा रहे हैं कि ज़्यादा आराम भी इंसान को खोखला बना सकता है।"),
C("🌱","प्रकृति और मन",["हरियाली से मन शांत","पक्षियों की आवाज़ से सुकून","सूरज की सुबह की रोशनी","प्रकृति से जुड़ाव उपचार जैसा"],"प्रकृति का मन पर बहुत अच्छा असर पड़ता है। जब हम हरे पेड़ों के बीच या खुले आसमान के नीचे होते हैं, तो मन अपने आप शांत होने लगता है। वैज्ञानिक भी मानते हैं कि हरियाली में कुछ देर बिताने से तनाव कम होता है। सुबह की ताज़ी हवा और सूरज की रोशनी हमारे शरीर को ऊर्जा देती है। इसलिए कवि प्रकृति की महिमा गाते हैं। आप भी रोज़ थोड़ी देर बाहर पेड़ों और पक्षियों को देखिए, पढ़ाई के बीच कुछ मिनट की यह सैर बहुत तरोताज़ा कर देती है।"),
C("🚜","आज के गाँव की सच्चाई",["गाँव में भी अब सड़कें, बिजली, मोबाइल","खेती में कठिनाइयाँ","रोज़गार की कमी, पलायन","फिर भी शांति और अपनापन"],"कवि ने गाँव की जो तस्वीर बनाई, वह थोड़ी आदर्श है। आज के गाँव में कई चुनौतियाँ भी हैं। खेती में मौसम की मार, पानी और आय की समस्या, रोज़गार की कमी और इसी वजह से युवाओं का शहर जाना। साथ ही गाँव में सड़कें, बिजली और मोबाइल जैसी सुविधाएँ भी आ चुकी हैं। फिर भी, गाँव का अपनापन, खुला वातावरण और सामुदायिक भावना आज भी बहुत क़ीमती है। कविता पढ़कर हमें यह सोचना चाहिए कि गाँव को सुविधाओं के साथ-साथ उसकी शांति भी बचाकर रखनी है।"),
C("📝","शब्दार्थ दोहराइए",["कंट्री यानी देहात","टाउन यानी शहर","वर्चू यानी सद्गुण","हेल्थ और फ़ील्ड्स"],"चलिए शब्द दोहराएँ। कंट्री यानी देहात, टाउन यानी शहर, वर्चू यानी सद्गुण, हेल्थ यानी स्वास्थ्य और फ़ील्ड्स यानी खेत। इनके साथ ग्रोव यानी छोटा बाग़, पीस यानी शांति और नेचर यानी प्रकृति भी याद कर लीजिए। अब एक अभ्यास कीजिए। इन शब्दों से अपने वाक्य बनाइए, जैसे विलेज लाइफ़ इज़ पीसफ़ुल, यानी गाँव का जीवन शांत है। और फ़्रेश एयर गिव्ज़ गुड हेल्थ, यानी ताज़ी हवा अच्छा स्वास्थ्य देती है। लिखने से शब्द पक्के याद रहते हैं।"),
C("🔤","व्याकरण: अर्थ में विरोध",["कंट्री बनाम टाउन","गॉड बनाम मैन","विरोधी शब्द कविता सजाते हैं","एंटोनिम की सूची बनाइए"],"इस कविता की पहली पंक्ति में विरोधी जोड़ों का सुंदर प्रयोग है, कंट्री और टाउन, गॉड और मैन। इन्हें एंटोनिम यानी विलोम शब्द कहते हैं। विलोम शब्दों से कविता में संतुलन और असर आता है। अब आप कुछ विलोम शब्द सीखिए। क्विट का विलोम नॉइज़ी, फ़्रेश का स्टेल, हेल्दी का अनहेल्दी, और रिच का पुअर। इनसे वाक्य बनाइए, जैसे द विलेज इज़ क्विट, बट द सिटी इज़ नॉइज़ी। यानी गाँव शांत है, पर शहर शोरगुल भरा है। रोज़ पाँच नए विलोम जोड़ों का अभ्यास कीजिए।"),
C("🧠","कविता के भाव की समीक्षा",["कवि का दृष्टिकोण गाँव के पक्ष में","शहर की सुविधाएँ भी सच","संतुलन सबसे अच्छा","अपनी राय तर्क से रखिए"],"अब थोड़ा सोचिए कि क्या कवि की बात पूरी तरह सही है। कवि गाँव के प्रेमी हैं, इसलिए वे गाँव की तरफ़दारी करते हैं। पर शहर में भी बहुत अच्छी बातें हैं, जैसे अच्छी शिक्षा, अस्पताल और रोज़गार। इसलिए सबसे अच्छा यह है कि संतुलन रहे, यानी शहर की सुविधाएँ भी मिलें और गाँव की शांति भी न खोए। परीक्षा में अगर आपसे राय पूछी जाए, तो अपनी बात तर्क के साथ लिखिए और कविता के कम से कम एक भाव का उल्लेख कीजिए। तर्क के साथ लिखा उत्तर हमेशा अच्छे अंक पाता है।"),
C("📌","कविता का सार",["ईश्वर ने गाँव, मनुष्य ने शहर बनाया","गाँव में स्वास्थ्य और सद्गुण","शहर के अमीरों पर व्यंग्य","संदेश: प्रकृति के पास रहें"],"अब कविता का सार दोहरा लें। विलियम काउपर की इस कविता में कहा गया है कि गाँव प्रकृति की रचना है और शहर मनुष्य की। गाँव के खेत और बाग़ों में स्वास्थ्य और सद्गुण मिलते हैं, जो जीवन की कड़वाहट को मीठा बना देते हैं। कवि शहर के आरामपसंद अमीरों पर हल्का व्यंग्य करते हैं। कविता का संदेश यह है कि हमें प्रकृति के पास रहना चाहिए और सादे जीवन का महत्व समझना चाहिए। इसे अपने शब्दों में पाँच वाक्यों में लिखकर देखिए।"),
C("❓","संभावित परीक्षा प्रश्न",["कवि कौन हैं","पहली पंक्ति का भाव","कवि गाँव को क्यों पसंद करते हैं","शहर के अमीरों पर व्यंग्य"],"परीक्षा के प्रश्न देखिए। पहला, कवि कौन हैं? उत्तर, विलियम काउपर, इंग्लैंड के। दूसरा, पहली पंक्ति का भाव क्या है? उत्तर, ईश्वर ने गाँव बनाया और मनुष्य ने शहर। तीसरा, कवि गाँव को क्यों पसंद करते हैं? उत्तर, क्योंकि वहाँ शांति, स्वास्थ्य और सद्गुण मिलते हैं। चौथा, व्यंग्य का आशय? उत्तर, आरामपसंद शहरी अमीर आलस से थके रहते हैं और जीवन का असली सुख नहीं पाते। उत्तर पूरे वाक्य में लिखिए।"),
Q("आपको गाँव का जीवन ज़्यादा पसंद है या शहर का, और क्यों?","अपनी पसंद चुनिए और कम से कम दो कारण दीजिए, जैसे शांति, सुविधा, अवसर या अपनापन।","एक सोचने वाला प्रश्न। आपको गाँव का जीवन ज़्यादा पसंद है या शहर का, और क्यों? सोचिए। ... अपनी पसंद चुनिए और कम से कम दो कारण दीजिए, जैसे शांति, सुविधा, अवसर या अपनापन। कारण के साथ लिखा उत्तर हमेशा अच्छा माना जाता है।"),
],7)
